// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate for smooth UI motion

// Load fonts at module level
const { fontFamily: bebasFamily } = loadBebas();
const { fontFamily: interFamily } = loadInter();



export type LowerThirdProps = Record<string, any>;

const LowerThird: React.FC<LowerThirdProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  titleLine1 = "LATE NIGHT RUN",
  titleLine2 = "SUMMER 2",
  locationText = "SOMEWHERE IN BANE WORLD",
  accentColor = "#00E5FF", // Teal indicator
  panelOpacity = 0.85,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080; 

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const durationInFrames = Math.round(durationInSeconds * fps);

  // Animation Timing Constants
  const entranceDuration = Math.round(fps * 0.6); // 0.6s entrance
  const exitDuration = Math.round(fps * 0.5); // 0.5s exit
  const exitStartFrame = durationInFrames - exitDuration;

  // Entrance Interpolations
  // Using an ease-out curve for a fast snap into place without bounce
  const enterProgress = interpolate(
    frame,
    [0, entranceDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );

  // Exit Interpolations
  const exitProgress = interpolate(
    frame,
    [exitStartFrame, durationInFrames],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.quad) }
  );

  // Derived Animated Values
  // Slides ~40 canvas-scaled pixels from left
  const translateX = interpolate(enterProgress, [0, 1], [-60 * s, 0]); 
  // Combined Opacity: Fades in, then fades out
  const baseOpacity = interpolate(enterProgress, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });
  const finalOpacity = interpolate(exitProgress, [0, 1], [baseOpacity, 0]);
  
  // Quick blur on entrance
  const blurAmount = interpolate(enterProgress, [0, 0.7], [15 * s, 0], { extrapolateRight: "clamp" });

  // Panel Dimensions & Geometry
  const panelW = 900 * s;
  const panelH = 260 * s;
  const cs = 8 * s;  // Small chamfer (top-left, bottom-left)
  const cl = 32 * s; // Large chamfer (top-right, bottom-right)

  // Constructing the SVG path for the chamfered background panel
  const panelPath = `
    M 0,${cs} 
    L ${cs},0 
    L ${panelW - cl},0 
    L ${panelW},${cl} 
    L ${panelW},${panelH - cl} 
    L ${panelW - cl},${panelH} 
    L ${cs},${panelH} 
    L 0,${panelH - cs} 
    Z
  `;

  // Layout Positions
  const containerLeft = width * 0.08;
  const containerBottom = height * 0.12;

  // Interior Layout Constants
  const indicatorLeft = 24 * s;
  const indicatorTop = 36 * s;
  const indicatorWidth = 6 * s;
  const indicatorHeight = 110 * s;
  
  const textLeft = indicatorLeft + indicatorWidth + 24 * s;
  const separatorY = 175 * s;
  const crosshairX = panelW - 60 * s;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Main Animated Container */}
      <div
        style={{
          position: "absolute",
          left: containerLeft,
          bottom: containerBottom,
          width: panelW,
          height: panelH,
          opacity: finalOpacity,
          transform: `translateX(${translateX}px)`,
          filter: `blur(${blurAmount}px)`,
          transition: "none",
        }}
      >
        
        {/* Background SVG Layer */}
        <svg 
          width={panelW} 
          height={panelH} 
          viewBox={`0 0 ${panelW} ${panelH}`}
          style={{ position: "absolute", top: 0, left: 0 }}
        >
          {/* Glass Panel Background */}
          <path 
            d={panelPath} 
            fill={`rgba(20, 20, 22, ${panelOpacity})`} 
            stroke="rgba(255, 255, 255, 0.25)" 
            strokeWidth={1.5 * s} 
          />
          
          {/* Teal Indicator Line */}
          <rect 
            x={indicatorLeft} 
            y={indicatorTop} 
            width={indicatorWidth} 
            height={indicatorHeight} 
            fill={accentColor} 
          />

          {/* Thin Separator Line */}
          <line 
            x1={indicatorLeft} 
            y1={separatorY} 
            x2={panelW - 24 * s} 
            y2={separatorY} 
            stroke="rgba(255, 255, 255, 0.4)" 
            strokeWidth={1.5 * s} 
          />

          {/* Technical Crosshair Bottom Right */}
          <line 
            x1={crosshairX - 12 * s} 
            y1={separatorY} 
            x2={crosshairX + 12 * s} 
            y2={separatorY} 
            stroke="rgba(255, 255, 255, 0.6)" 
            strokeWidth={1 * s} 
          />
          <line 
            x1={crosshairX} 
            y1={separatorY - 12 * s} 
            x2={crosshairX} 
            y2={separatorY + 12 * s} 
            stroke="rgba(255, 255, 255, 0.6)" 
            strokeWidth={1 * s} 
          />
        </svg>

        {/* HTML Text Overlay Layer for Sharpness */}
        <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}>
          
          {/* Main Titles */}
          <div style={{ 
            position: "absolute", 
            left: textLeft, 
            top: 28 * s,
            display: "flex",
            flexDirection: "column",
            gap: 2 * s
          }}>
            <h1 style={{
              margin: 0,
              fontFamily: bebasFamily,
              fontSize: 72 * s,
              color: "#FFFFFF",
              lineHeight: 0.9,
              letterSpacing: "0.02em",
              fontWeight: 400,
            }}>
              {titleLine1}
            </h1>
            <h2 style={{
              margin: 0,
              fontFamily: bebasFamily,
              fontSize: 72 * s,
              color: "#FFFFFF",
              lineHeight: 0.9,
              letterSpacing: "0.02em",
              fontWeight: 400,
            }}>
              {titleLine2}
            </h2>
          </div>

          {/* Subtext Location Stamp */}
          <p style={{
            position: "absolute",
            left: indicatorLeft,
            top: separatorY + 16 * s,
            margin: 0,
            fontFamily: interFamily,
            fontSize: 22 * s,
            color: "rgba(255, 255, 255, 0.9)",
            letterSpacing: "0.15em",
            fontWeight: 500,
            textTransform: "uppercase"
          }}>
            {locationText}
          </p>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LowerThird;